clc; clear; 
%%

m = 10;     % mass (kg)
k = 1000;   % spring constant (N/m)
c = 10;     % damping coefficient (Ns/m)
u = 0;      % external force input (N)
%%
% eig(A)
%%
A = [0 1; -k/m -c/m];   % state matrix
B = [0; 1/m];           % input matrix
C = [1 0];              % output matrix

% Observer pole locations (must be faster than system poles)
p_o = [-2.5 + 9.7i, -2.5 - 9.7i];

% Observer gain (dual system approach)
Ke = place(A', C', p_o)';

t_sim = 0:0.01:10; % simulation time vector
%%
% --- System dynamics ---
% function dx = smd(x, A, B, u)
%     dx = A*x + B*u;
% end
% 
% % --- Observer dynamics ---
% function dx_hat = obs(t_o, x_hat, A, B, C, u, Ke, y, t)
%     y_interp = interp1(t, y, t_o);  % interpolate measurement
%     dx_hat = A*x_hat + B*u + Ke*(y_interp - C*x_hat);
% end

%%
x0 = [-2; 0;10;0]; % released from x = -2 m at rest
% Simulate system + observer using ode45
[t, X] = ode45(@(t, X) smd_obs(t, X, A, B, C, Ke, u), t_sim, x0);

% Extract results
x      = X(:, 1:2);          % true state [pos, vel]
x_hat  = X(:, 3:4);          % estimated state
error  = x - x_hat;          % estimation error

% ---------------------- Plot results ---------------------------
figure; %[output:4f9d0c68]
subplot(3,1,1); %[output:4f9d0c68]
plot(t, x(:,1), 'b', 'LineWidth', 1.5); hold on; %[output:4f9d0c68]
plot(t, x_hat(:,1), '--r', 'LineWidth', 1.2); %[output:4f9d0c68]
ylabel('Position (m)'); %[output:4f9d0c68]
legend('True','Estimated'); %[output:4f9d0c68]
title('Observer Performance: Position'); %[output:4f9d0c68]

subplot(3,1,2); %[output:4f9d0c68]
plot(t, x(:,2), 'b', 'LineWidth', 1.5); hold on; %[output:4f9d0c68]
plot(t, x_hat(:,2), '--r', 'LineWidth', 1.2); %[output:4f9d0c68]
ylabel('Velocity (m/s)'); %[output:4f9d0c68]
legend('True','Estimated'); %[output:4f9d0c68]
title('Observer Performance: Velocity'); %[output:4f9d0c68]

subplot(3,1,3); %[output:4f9d0c68]
plot(t, error(:,1), 'k', 'LineWidth', 1.2); hold on; %[output:4f9d0c68]
plot(t, error(:,2), '--g', 'LineWidth', 1.2); %[output:4f9d0c68]
xlabel('Time (s)'); %[output:4f9d0c68]
ylabel('Error'); %[output:4f9d0c68]
legend('Position Error','Velocity Error'); %[output:4f9d0c68]
title('Estimation Errors'); %[output:4f9d0c68]

%%
function dX = smd_obs(~, X, A, B, C, Ke, u)
    % Separate true and estimated states
    x = X(1:2);
    x_hat = X(3:4);
    
    % True system
    dx = A*x + B*u;
    y = C*x;  % measured output (no noise)
    
    % Observer
    dx_hat = A*x_hat + B*u + Ke*(y - C*x_hat);
    
    % Combine derivatives
    dX = [dx; dx_hat];
end


